using UnityEngine;

public class GemstoneManager : MonoBehaviour
{
    // Gemstone prefab
    public GameObject gemstonePrefab;

    // Grid dimensions
    public int gridWidth;
    public int gridHeight;

    // Gemstone array
    public Gemstone[] gemstones;

    // Current score
    public int score;

    void Start()
    {
        // Initialize gemstone array
        gemstones = new Gemstone[gridWidth * gridHeight];

        // Instantiate gemstones in grid
        for (int i = 0; i < gridWidth * gridHeight; i++)
        {
            GameObject gemstoneObject = Instantiate(gemstonePrefab, new Vector3(i % gridWidth, i / gridWidth, 0), Quaternion.identity);
            Gemstone gemstone = gemstoneObject.GetComponent<Gemstone>();
            gemstones[i] = gemstone;
        }
    }

    void Update()
    {
        // Check for match-3
        CheckForMatch3();
    }

    void CheckForMatch3()
    {
        // Iterate through grid
        for (int i = 0; i < gridWidth * gridHeight; i++)
        {
            // Get neighboring gemstones
            Gemstone currentGemstone = gemstones[i];
            Gemstone leftGemstone = i > 0 ? gemstones[i - 1] : null;
            Gemstone rightGemstone = i < gridWidth * gridHeight - 1 ? gemstones[i + 1] : null;
            Gemstone upGemstone = Mathf.FloorToInt(i / (float)gridWidth) > 0 ? gemstones[i - gridWidth] : null;
            Gemstone downGemstone = Mathf.FloorToInt(i / (float)gridWidth) < gridHeight - 1 ? gemstones[i + gridWidth] : null;

            // Check for match-3
            if (currentGemstone.color == leftGemstone.color && leftGemstone != null
                || currentGemstone.color == rightGemstone.color && rightGemstone != null
                || currentGemstone.color == upGemstone.color && upGemstone != null
                || currentGemstone.color == downGemstone.color && downGemstone != null)
            {
                // Make match-3
                MakeMatch3(i);
            }
        }
    }

    void MakeMatch3(int index)
    {
        // Remove gemstone
        Gemstone gemstone = gemstones[index];
        gemstones[index] = null;
        Destroy(gemstone.gameObject);

        // Increase score
        score += gemstone.color * 10;
    }
}
