let predictiveSearchResults = document.getElementById('predictive-search-results');

const handlePredictiveSearch = (searchTerm) => {
  // Make API request to Google Custom Search JSON API
  fetch(`https://customsearch.googleapis.com/cse/v1/cse/quicksearch?cx=YOUR_SEARCH_ENGINE_ID&q=${searchTerm}`)
    .then(response => response.json())
    .then(data => {
      const results = data.items.map((result) => {
        return `<li><a href="${result.link}">${result.title}</a></li>`;
      }).join('');
      predictiveSearchResults.innerHTML = results;
    });
};

searchInput.addEventListener('input', (e) => {
  const searchTerm = e.target.value;
  handlePredictiveSearch(searchTerm);
});
